+import { isBoundaryBlockKind, type WorkflowBlock } from "@reqflow/core";
+
+export type FilterPreset = "customer-facing" | "all-relevant" | "custom";
+const PRESETS = {
+  "customer-facing": {
+    criterion: "Keep information relevant to customer-facing vehicle attributes. Keep mixed-topic items intact if any part is relevant.",
+    include: "Features, equipment, comfort, space, usability, infotainment, digital services, design, perceived quality, driving experience, range, charging, variants and packages.",
+    exclude: "Pure regulatory or homologation topics, engineering specifications, pricing and business cases without customer-facing information.",
+    examples: "Keep: The seat is uncomfortable on long journeys.\nExclude: The component must meet a homologation standard.\nReview: Ambiguous or conflicting information without enough context.",
+  },
+  "all-relevant": {
+    criterion: "Keep all information relevant to the vehicle and market scope from Settings. Preserve mixed-topic items intact if any part is relevant.",
+    include: "Customer feedback and relevant equipment, sales, study, competitor, review and trend context.",
+    exclude: "Only clearly unrelated information. Do not exclude uncertainty or conflicting evidence merely because it disagrees.",
+    examples: "Keep: Relevant customer feedback or market context.\nExclude: Unrelated content about a different product.\nReview: Relevance cannot be established from available fields.",
+  },
+};
+
+/** Called only by Apply preset; custom is deliberately a no-op. */
+export function applyFilterPreset(params: WorkflowBlock["params"], preset: FilterPreset) {
+  return preset === "custom" ? { ...params } : { ...params, ...PRESETS[preset] };
+}
+
+export function filterBypassed(block: WorkflowBlock): boolean {
+  return !!block.inner && (block.inner.edges.length > 0 || block.inner.blocks.some((child) => !isBoundaryBlockKind(child.kind)));
+}
