+import { FilterReview, FilterReviewState, type FilterReport, type WorkflowRun } from "@reqflow/core";
+
+export type FilterDecision = FilterReport["decisions"][number];
+export const FILTER_TABS = [{ value: "keep", label: "Kept" }, { value: "exclude", label: "Excluded" }, { value: "review", label: "Needs review" }] as const;
+export type FilterTab = (typeof FILTER_TABS)[number]["value"];
+
+export function safeFilterJson(value: unknown): string {
+  try { return JSON.stringify(value, null, 2) ?? "Not recorded"; }
+  catch { return "Saved value cannot be displayed as JSON."; }
+}
+
+export function filterRows(report: FilterReport) {
+  const originals = new Map(report.originalInput[report.primaryLayer].map((item) => [item.id, item]));
+  return report.decisions.map((decision) => ({
+    decision,
+    original: originals.get(decision.itemId),
+    search: `${safeFilterJson(decision)} ${safeFilterJson(originals.get(decision.itemId))} ${decision.quotes.map((quote) => {
+      const record = report.originalInput.records.find((item) => item.id === quote.recordId);
+      const source = report.originalInput.sources.find((item) => item.id === record?.sourceId);
+      return `${record?.locator ?? ""} ${source?.title ?? ""} ${source?.uri ?? ""}`;
+    }).join(" ")}`.toLowerCase(),
+  }));
+}
+
+export function filterPage(rows: ReturnType<typeof filterRows>, tab: FilterTab, query: string, requestedPage: number) {
+  const counts = { keep: 0, exclude: 0, review: 0 };
+  for (const row of rows) counts[row.decision.outcome]++;
+  const matching = rows.filter((row) => row.decision.outcome === tab && row.search.includes(query.trim().toLowerCase()));
+  const pages = Math.max(1, Math.ceil(matching.length / 20));
+  const page = Math.min(pages - 1, Math.max(0, Math.floor(requestedPage) || 0));
+  return { counts, total: matching.length, pages, page, rows: matching.slice(page * 20, page * 20 + 20) };
+}
+
+export function filterDisposition(item: FilterDecision): string {
+  return `${item.forwarded ? "Forwarded" : "Held / not forwarded"}${item.retainedAsContext ? "; retained as supporting context" : "; not retained as context"}`;
+}
+
+export function pendingFilterOverride(report: FilterReport, item: FilterDecision, state: FilterReviewState | null) {
+  return state?.overrides.find((override) => override.itemId === item.itemId && override.itemHash === item.itemHash && override.configurationHash === report.configurationHash);
+}
+
+export function filterRestoreGuard(run: WorkflowRun | null, report: FilterReport, item: FilterDecision, state: FilterReviewState | null): string | null {
+  if (!run || run.id !== report.runId) return "Open the matching saved run before restoring.";
+  if (run.status !== "completed" && run.status !== "waiting_for_review") return "Restore is available only for completed runs or runs waiting for review.";
+  if (!report.decisions.includes(item)) return "Select an item from this saved report.";
+  if (!(item.outcome === "exclude" || (item.outcome === "review" && !item.forwarded))) return "Only excluded items or held review items can be restored.";
+  if (!state) return "Read pending restore state before saving.";
+  if (pendingFilterOverride(report, item, state)) return "A matching restore is already pending for the next full run.";
+  return null;
+}
+
+export function filterRestoreRequest(run: WorkflowRun | null, report: FilterReport, item: FilterDecision, state: FilterReviewState | null, rationale: string) {
+  const error = filterRestoreGuard(run, report, item, state);
+  if (error) throw new Error(error);
+  return FilterReview.parse({ expectedVersion: FilterReviewState.parse(state).version, itemIds: [item.itemId], rationale });
+}
+
+/** Both successes and failures must still belong to the active run/block selection. */
+export async function settleFilterRequest<T>(read: () => Promise<T>, current: () => boolean, success: (value: T) => void, failure: (message: string) => void) {
+  try {
+    const result = await read();
+    if (current()) success(result);
+  } catch (cause) {
+    if (current()) failure(cause instanceof Error ? cause.message : String(cause));
+  }
+}
