+export function filterProvenance(report: FilterReport, original: ReturnType<typeof filterRows>[number]["original"]) {
+  if (!original) return null;
+  const object = original as unknown as Record<string, unknown>;
+  const strings = (value: unknown): string[] => Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
+  const findingIds = new Set([...strings(object.findingIds), ...strings(object.conflictingFindingIds)]);
+  const findings = report.originalInput.findings.filter((item) => findingIds.has(item.id));
+  const evidence = [...(Array.isArray(object.evidence) ? object.evidence : []), ...findings.flatMap((item) => item.evidence)] as Array<{ sourceId?: string; recordId?: string; locator?: string; excerpt?: string }>;
+  const sourceIds = new Set([...strings(object.sourceIds), ...evidence.map((ref) => ref.sourceId), object.sourceId, object.id]);
+  const recordIds = new Set(evidence.map((ref) => ref.recordId));
+  return {
+    locator: object.locator,
+    sources: report.originalInput.sources.filter((item) => sourceIds.has(item.id)),
+    records: report.originalInput.records.filter((item) => recordIds.has(item.id)),
+    findings,
+    evidence,
+  };
+}
